files./etc/bind/named.conf:
// auth1: an authoritative-only BIND instance for the lab
include "/etc/bind/rndc.key";
controls { inet 127.0.0.1 port 953 allow { 127.0.0.1; } keys { "rndc-key"; }; };
options {
	directory "/var/cache/bind/netlab-dns-auth1";
	pid-file none;
	listen-on { 198.18.52.2; 198.18.52.3; 127.0.0.1; };
	listen-on-v6 { none; };
	recursion no;
	dnssec-validation no;
	minimal-responses no-auth-recursive;
	notify no;
};
logging {
	channel out { stderr; severity info; print-time yes; };
	category default { out; };
	category queries { out; };
	category lame-servers { null; };
};
view "internal" {
	match-clients { 198.18.60.2; };
	zone "corp.test" { type primary; file "/etc/bind/corp.internal.db"; };
	zone "secure.test" { type primary; file "/etc/bind/secure.test.signed"; };
	zone "expired.test" { type primary; file "/etc/bind/expired.test.signed"; };
};
view "external" {
	match-clients { any; };
	zone "corp.test" { type primary; file "/etc/bind/corp.external.db"; };
	zone "secure.test" { type primary; file "/etc/bind/secure.test.signed"; };
	zone "expired.test" { type primary; file "/etc/bind/expired.test.signed"; };
};

